1	/* Wren's design system, version 1: the components.
2	
3	   What every screen is made of, whoever serves it - a card, a button, a field,
4	   a table, a pill - built from the tokens and nothing else. A groove
5	   links this file itself, from its own fragments, because it was built against
6	   it: a hub is not trusted to happen to have it. Linking it again where a hub
7	   already has is harmless; the rules are the same rules.
8	
9	   Everything here is in a layer, so a groove's own stylesheet beats it without
10	   a specificity contest. Two layers: `base` is how bare elements look, which
11	   is the part most likely to surprise somebody - a full-width input, a
12	   coloured link - and so the part that most needs to lose. `components` is
13	   the classes.
14	
15	   What is *not* here is anything only one host or one groove uses. A hub's
16	   sidebar is the hub's; a groove's metronome is the groove's. When two teams
17	   both need something, it moves here, and gets a version. */
18	
19	@layer tokens, base, components, host;
20	
21	/* ------------------------------------------------------------------ base */
22	
23	@layer base {
24	  *, *::before, *::after { box-sizing: border-box; }
25	  html { -webkit-text-size-adjust: 100%; }
26	  html, body { margin: 0; padding: 0; }
27	  body {
28	    background: var(--bg);
29	    color: var(--fg);
30	    font: 400 var(--text-base)/1.5 var(--font-sans);
31	    -webkit-font-smoothing: antialiased;
32	  }
33	  [hidden] { display: none !important; }
34	  button, input, select, textarea { font: inherit; color: inherit; }
35	  button { cursor: pointer; }
36	  a { color: var(--accent); text-underline-offset: 0.18em; }
37	  a:hover { color: var(--accent-hover); }
38	  :focus-visible { outline: none; box-shadow: var(--ring); border-radius: var(--radius-sm); }
39	  code { font-family: var(--font-mono); font-size: 0.9em; background: var(--surface-sunken); padding: 0.1em 0.35em; border-radius: var(--radius-sm); }
