2	
3	   <button class="btn" aria-label="Close"><span class="icon icon-close"></span></button>
4	
5	   The glyph is a mask over currentColor, so it is the colour of the text
6	   beside it, in every theme and in forced colours. The <span> says nothing;
7	   the control around it has the name. Each glyph is a token, so a host can
8	   draw its own: --icon-close: url(/host/close.svg). */
9	
10	@layer tokens, base, components, host;
11	
